insert into bullets (ref, text, source_org, source_period, tags, variants, provenance, status) values ('BL-008', 'Secured $3M in working capital, inventory financing, and revolving credit to fund production and market entry, preventing supply interruption through peak demand.', 'COMARKCO', '2023-2025', ARRAY['finance','capital','operations'], ARRAY['leadership'], 'measured', 'draft');
