insert into bullets (ref, text, source_org, source_period, tags, variants, provenance, status) values ('BL-043', 'Automated and streamlined departmental administrative processes, reducing turnaround time and operating cost.', 'UNIVERSITY OF CALIFORNIA, IRVINE', '2013-2018', ARRAY['process','automation','efficiency'], ARRAY['engineer'], 'stated', 'draft');
insert into answers (ref, question_type, text, slots, status, tags) values
('A1', 'why_company', 'What caught me about {{company}} is {{specific_signal}} — that''s the exact problem I''ve spent the last year on. I''ve been building AI automation systems end to end, most recently an autonomous decision platform running live in production, and what I want next is to do that inside an organization where the leverage is bigger than a five-person shop. {{role_specific_hook}}', ARRAY['company','specific_signal','role_specific_hook'], 'draft', ARRAY['why_company']),
('A2', 'automation_experience', E'I build and operate production AI systems rather than pilots. The clearest example: an autonomous forecasting and decision-automation platform I architected and shipped that runs live today — 68 API endpoints, 540 configurable strategy profiles, ensemble modeling, and automated risk controls with real-time hedging. I also built the statistical validation layer that gates it, so no strategy reaches live execution without passing walk-forward testing, Monte Carlo simulation, and drawdown analysis.\n\nBefore the technical work I spent twelve years running operations — scaling a CPG brand from $250K to $12M, building the finance, logistics, and compliance systems behind it. That combination is the useful part: I build automations against how a business actually runs, not against an idealized process diagram.', NULL, 'ready', ARRAY['automation_experience']),
('A3', 'why_leaving_own_company', 'NEEDS INPUT: draft exists from a past conversation but is unconfirmed — see docs/ANSWER_LIBRARY.md A3 for the drafted text and confirm before this ships.', NULL, 'needs_input', ARRAY['why_leaving']),
('A4', 'ic_vs_leadership', 'I''ve done the leadership track and I''m good at it. I''m better at building, and I enjoy it more. I''m looking for a role where the deliverable is a working system rather than a headcount plan. I''m not looking to manage people, and I''d rather say that clearly up front than discover a mismatch in month three.', NULL, 'ready', ARRAY['ic_vs_leadership']),
('A5', 'salary_expectations', '{{target_range}} base, flexible depending on total package and equity.', ARRAY['target_range'], 'ready', ARRAY['salary']),
('A6', 'biggest_system_built', 'NEEDS INPUT: composed from A2''s first paragraph plus an additional closing line — see docs/ANSWER_LIBRARY.md A6 for the full text.', NULL, 'draft', ARRAY['biggest_system']),
('A7', 'tell_me_about_a_failure', E'While drafting a resume I caught a bullet describing an internal system as built and deployed. I''d specified it in detail. I hadn''t shipped it. Nothing in my notes distinguished those two states — six weeks on, an ambitious plan and a running system read identically — and it was one screen-share question away from being indefensible.\n\nThe fix was structural, not a promise to be more careful: every claim in my library now carries a provenance tag, and a ten-line validator refuses to assemble a document containing an unverifiable one.\n\nThe general version matters more than the resume version. When a language model summarizes your own notes back to you, it will quietly promote intention to accomplishment, and it will do it in your voice. Any system putting model output in front of people needs a layer that asks where each claim came from.', NULL, 'ready', ARRAY['failure']),
('A8', 'ai_deployment_philosophy', E'Start with where the blast radius lands, not with what''s possible. The capability is usually trivial now; the question is what breaks when it''s wrong and who finds out.\n\nA concrete example: I built a pipeline for my own job search that automates discovery, screening, and document assembly. The version that also auto-submits applications was about three more hours of work. I didn''t build it — ATS terms prohibit it, the platforms detect it, and a flag in a shared instance quietly costs you every company on that platform. Most AI deployment decisions look like that.\n\nSecond thing: choose the boring architecture. That pipeline has no vector store and no agent framework, because the corpus is a few hundred rows and keyword matching plus one model call is correct. Reaching for the sophisticated option when the simple one works is the most common failure I see in AI projects right now.', NULL, 'draft', ARRAY['ai_philosophy']),
('A9', 'automation_philosophy_oneline', 'Automate the work, keep the human on the decisions that have consequences — and be deliberate about which is which.', NULL, 'draft', ARRAY['automation_philosophy']),
('A10', 'domain_gap', 'I haven''t. What I have is twelve years of learning new operating environments fast — CPG, healthcare services, digital media, higher ed — and the automation problems rhyme across all of them: manual reconciliation between systems, reporting nobody trusts, workflows that exist because someone left. I''d expect the first month to be mostly listening.', ARRAY['industry'], 'draft', ARRAY['domain_gap']),
('B1', 'influence_without_authority', 'NEEDS INPUT: a specific instance of influencing a team you didn''t own, likely from Comarkco as a fractional exec. No draft exists — see docs/ANSWER_LIBRARY.md B1.', NULL, 'needs_input', ARRAY['behavioral']),
('B2', 'conflict_or_disagreement', 'NEEDS INPUT: a specific instance of a real conflict/disagreement. No draft exists — see docs/ANSWER_LIBRARY.md B2.', NULL, 'needs_input', ARRAY['behavioral']),
('B3', 'reference_safe_reason_for_leaving', 'NEEDS INPUT: reference-check-safe framing for leaving Worksite Labs and Comarkco — what actually happened and what those employers would say. Shapes several other answers. No draft exists — see docs/ANSWER_LIBRARY.md B3.', NULL, 'needs_input', ARRAY['reason_for_leaving']),
('B4', 'availability_start_date', 'NEEDS INPUT: availability / notice period. No draft exists — see docs/ANSWER_LIBRARY.md B4.', NULL, 'needs_input', ARRAY['logistics']),
('B5', 'comarkco_equity_outcome', 'NEEDS INPUT: whether the Comarkco equity paid off — materially affects how A3 should be framed. No draft exists — see docs/ANSWER_LIBRARY.md B5.', NULL, 'needs_input', ARRAY['equity']),
('B6', 'three_year_vision', 'NEEDS INPUT: what you actually want to be doing in three years — needs careful framing around the ventures, not an invented ambition. No draft exists — see docs/ANSWER_LIBRARY.md B6.', NULL, 'needs_input', ARRAY['career_vision']),
('B7', 'recurring_interview_stumper', 'NEEDS INPUT: any question that has reliably tripped you up in past interviews — highest-value entry in this file once filled. No draft exists — see docs/ANSWER_LIBRARY.md B7.', NULL, 'needs_input', ARRAY['interview_prep']);
