-- Phase 1 seed: bullets (from scripts/build_resumes.js) + answers (from docs/ANSWER_LIBRARY.md)
-- Every bullet ships status='draft' regardless of proposed provenance below —
-- the provenance validator refuses anything not explicitly 'verified'.
-- Review docs/BULLET_LIBRARY_REVIEW.md, correct provenance where wrong, then flip
-- status to 'verified' per row (or in bulk) once confirmed.


-- answers table, schema per docs/ANSWER_LIBRARY.md
create table answers (
  id            bigserial primary key,
  ref           text unique not null,     -- A2
  question_type text not null,            -- why_company | automation_experience | ...
  text          text not null,
  slots         text[],                   -- {{company}}, {{specific_signal}}
  status        text default 'ready',     -- ready|draft|needs_input
  tags          text[],
  times_used    int default 0,
  last_used_at  timestamptz
);

-- READY / DRAFT entries seeded with their actual text. NEEDS YOU entries (A3, B1-B7)
-- are seeded with the *prompt describing what's needed*, never a fabricated answer —
-- their text field is what to fill in, not an answer.


